#!/usr/bin/env python3
"""
Round 112b (tiles), 29 September 2026.

The advertising, news and entertainment maps with both of their tabs (the
companies and who owns them), the Eyes network's entries that have no place,
and scripts/giga_points.py: the map's own copy of every school Giga maps.

Whole files, each written only if it differs.
"""
import base64, pathlib

FILES = {'sitemaps/site_world_advertising.places.geojson': '', 'sitemaps/site_world_advertising.boxes.json': '', 'sitemaps/site_world_news.places.geojson': '', 'sitemaps/site_world_news.boxes.json': '', 'sitemaps/site_world_entertainment.places.geojson': '', 'sitemaps/site_world_entertainment.boxes.json': '', 'sitemaps/site_eyes_network.unplaced.json': '', 'scripts/giga_points.py': ''}
DELETE = []


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round112b: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round112b: wrote {p}")
    for p in DELETE:
        f = pathlib.Path(p)
        if f.exists():
            f.unlink()
            print(f"round112b: deleted {p}")


if __name__ == "__main__":
    main()
